--
-- Table structure for table `parks`
--

CREATE TABLE `parks` (
  `id` bigint(20) NOT NULL,
  `access_information` text DEFAULT NULL,
  `best_time_to_visit` varchar(100) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `district` varchar(100) DEFAULT NULL,
  `ecosystem` longtext DEFAULT NULL,
  `elevation` varchar(50) DEFAULT NULL,
  `full_description` longtext NOT NULL,
  `history` longtext DEFAULT NULL,
  `internal_notes` longtext DEFAULT NULL,
  `is_active` bit(1) NOT NULL,
  `latitude` decimal(10,7) DEFAULT NULL,
  `location` text DEFAULT NULL,
  `longitude` decimal(10,7) DEFAULT NULL,
  `name` varchar(100) NOT NULL,
  `opening_hours` text DEFAULT NULL,
  `park_type` enum('CONSERVATION_AREA','FOREST_RESERVE','GAME_RESERVE','MARINE_PARK','NATIONAL_PARK','NATURE_RESERVE','WILDLIFE_RESERVE') NOT NULL,
  `primary_image` varchar(500) DEFAULT NULL,
  `region` varchar(100) DEFAULT NULL,
  `short_description` text NOT NULL,
  `size` varchar(50) DEFAULT NULL,
  `slug` varchar(150) DEFAULT NULL,
  `tags` text DEFAULT NULL,
  `updated_at` datetime(6) NOT NULL,
  `vegetation` longtext DEFAULT NULL,
  `wildlife` longtext DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Dumping data for table `parks`
--

INSERT INTO `parks` (`id`, `access_information`, `best_time_to_visit`, `created_at`, `district`, `ecosystem`, `elevation`, `full_description`, `history`, `internal_notes`, `is_active`, `latitude`, `location`, `longitude`, `name`, `opening_hours`, `park_type`, `primary_image`, `region`, `short_description`, `size`, `slug`, `tags`, `updated_at`, `vegetation`, `wildlife`) VALUES
(1, 'Accessible by road from Arusha (8-9 hours) or by air to Seronera, Kogatende, or Lobo airstrips. Multiple entry gates including Naabi Hill, Ndabaka, and Ikoma.', 'June to October (dry season for wildlife viewing), January to February (calving season)', '2025-12-31 23:59:37.000000', 'Serengeti', 'Grassland savanna, acacia woodlands, riverine forests, and open plains. The ecosystem supports diverse habitats from short grass plains to kopjes (rocky outcrops).', '920-1,850 meters', 'Serengeti National Park is a vast ecosystem in north-central Tanzania. Established in 1951, it covers 14,763 square kilometers of grassland plains, savanna, riverine forest, and woodlands. The park is divided into three regions: Serengeti Plains, Western Corridor, and Northern Serengeti. It borders the Maasai Mara National Reserve in Kenya to the north. The park is home to the largest lion population in Africa and hosts the spectacular Great Migration, one of the most impressive natural events on Earth. The name \"Serengeti\" comes from the Maasai language and means \"endless plains\".', 'Established in 1951 and designated as a UNESCO World Heritage Site in 1981. The area was first protected as a game reserve in 1929 before being upgraded to national park status.', NULL, b'1', -2.3333000, 'Northern Tanzania, 335 km northwest of Arusha', 34.8333000, 'Serengeti National Park', '6:00 AM - 6:00 PM daily', 'NATIONAL_PARK', NULL, 'Mara and Simiyu', 'One of the most famous wildlife sanctuaries in the world, known for the annual Great Migration of over 1.5 million wildebeest and 250,000 zebras.', '14,763 km²', 'serengeti-national-park', 'Big Five, Great Migration, Safari, Wildlife, UNESCO World Heritage, Lion, Wildebeest, Zebra, Kopjes, Savanna', '2025-12-31 23:59:37.000000', 'Grassland plains dominate with scattered acacia trees, particularly umbrella acacias. Western corridor features riverine forests along the Grumeti River. Kopjes support unique plant communities.', 'Home to the Big Five (lion, leopard, elephant, buffalo, rhinoceros) and hosts the Great Migration of over 2 million wildebeest, zebras, and gazelles. The park has Africa\'s largest lion population with over 3,000 lions. Other species include cheetahs, hyenas, giraffes, hippos, crocodiles, and over 500 bird species.'),
(2, 'Accessible by road from Arusha (3-4 hours). Main entrance at Lodoare Gate. Can be combined with Serengeti visits via Naabi Hill Gate.', 'June to October (dry season), December to March (green season)', '2025-12-31 23:59:37.000000', 'Ngorongoro', 'Highland plains, savanna, savanna woodlands, forests, and the volcanic crater ecosystem. Includes soda lakes, swamps, and montane forests on crater rims.', '1,030-3,648 meters (Loolmalasin peak)', 'The Ngorongoro Conservation Area is a protected area and UNESCO World Heritage Site located in the Crater Highlands of northeastern Tanzania. The area is named after Ngorongoro Crater, a large volcanic caldera formed when a giant volcano exploded and collapsed 2-3 million years ago. The crater floor, 600 meters deep and covering 260 square kilometers, is home to approximately 25,000 large animals. The conservation area also includes Olduvai Gorge, one of the most important paleoanthropological sites in the world. Unlike national parks, the Ngorongoro Conservation Area allows human habitation, with Maasai pastoralists living alongside wildlife.', 'Designated as a UNESCO World Heritage Site in 1979 and as an International Biosphere Reserve in 1981. The area was originally part of Serengeti National Park until it was separated in 1959 to create a multiple land use area.', NULL, b'1', -3.2000000, 'Crater Highlands, 180 km west of Arusha City', 35.4500000, 'Ngorongoro Conservation Area', '6:00 AM - 6:00 PM daily', 'CONSERVATION_AREA', NULL, 'Arusha', 'Home to the world\'s largest intact volcanic caldera and one of Africa\'s most spectacular wildlife viewing areas with the highest density of predators.', '8,292 km²', 'ngorongoro-conservation-area', 'Crater, UNESCO World Heritage, Big Five, Black Rhino, Maasai Culture, Olduvai Gorge, Volcanic Caldera, Wildlife Dense', '2025-12-31 23:59:37.000000', 'Ranges from short grass plains on the crater floor to montane forests on the crater rim. Includes fever tree forests, highland grasslands, and diverse plant communities supporting various ecological niches.', 'The crater hosts approximately 25,000 large mammals including the Big Five. It has the densest known population of lions in the world. The area is one of the few places in Africa where you can see the endangered black rhinoceros. Other species include elephants, buffaloes, hippos, wildebeest, zebras, elands, gazelles, and over 500 bird species including flamingos on Lake Magadi.'),
(3, 'Accessible by road from Arusha (2 hours). Main entrance at the northern gate. Good tarmac road to the park entrance.', 'June to October (dry season - best for wildlife concentration)', '2025-12-31 23:59:37.000000', 'Babati', 'Acacia woodlands, riverine forests, seasonal swamps, open grasslands, and ancient baobab-studded landscapes. The Tarangire River and Silale Swamp are key ecosystem features.', '900-1,250 meters', 'Tarangire National Park is Tanzania\'s sixth-largest national park, covering 2,850 square kilometers. Named after the Tarangire River that flows through the park, it serves as a vital water source during the dry season, attracting massive concentrations of wildlife. The park is renowned for having one of the highest elephant populations in Tanzania, with herds of up to 300 elephants common during the dry season. Ancient baobab trees dot the landscape, some over 1,000 years old. During the dry season (June-October), Tarangire has wildlife densities second only to Ngorongoro Crater.', 'Established as a national park in 1970. The area has been important to wildlife migration patterns for millennia, particularly for elephants moving between seasonal water sources.', NULL, b'1', -3.8333000, 'Northern Tanzania, 118 km southwest of Arusha', 36.0000000, 'Tarangire National Park', '6:00 AM - 6:00 PM daily', 'NATIONAL_PARK', NULL, 'Manyara', 'Famous for its huge elephant population, iconic baobab trees, and spectacular concentration of wildlife during the dry season.', '2,850 km²', 'tarangire-national-park', 'Elephants, Baobab Trees, Bird Watching, Wildlife, Dry Season Safari, Tarangire River, Migration, Big Cats', '2025-12-31 23:59:37.000000', 'Dominated by ancient baobab trees, umbrella acacias, and sausage trees. Swamp areas feature dense vegetation including palms and tall grasses. Open plains with scattered acacias.', 'Home to large elephant herds (up to 3,000 individuals), lions, leopards, cheetahs, and over 550 bird species making it a paradise for bird watchers. Other mammals include buffaloes, giraffes, wildebeest, zebras, impalas, elands, fringe-eared oryx, and pythons in the swamps.'),
(4, 'Accessible by road from Arusha (2 hours). Located on the main route to Serengeti and Ngorongoro. Good tarmac road to park entrance.', 'Year-round destination; July to October and January to February best for wildlife', '2025-12-31 23:59:37.000000', 'Monduli', 'Diverse ecosystems including groundwater forest, acacia woodland, open grassland, swamps, and the alkaline lake. The Great Rift Valley escarpment forms a dramatic backdrop.', '960-1,828 meters', 'Lake Manyara National Park is a compact gem located between Lake Manyara and the Great Rift Valley escarpment. Despite its small size, it hosts remarkable biodiversity. The park is famous for its unusual tree-climbing lions, which lounge in acacia branches during the heat of the day. The alkaline lake attracts thousands of flamingos, creating spectacular pink shores during certain seasons. The groundwater forest at the park entrance is one of the few in East Africa.', 'Established as a national park in 1960. The area was previously a hunting ground and gained protection due to its unique wildlife and ecological importance.', NULL, b'1', -3.5333000, 'Northern Tanzania, 126 km west of Arusha, near Great Rift Valley escarpment', 35.8333000, 'Lake Manyara National Park', '6:30 AM - 6:00 PM daily', 'NATIONAL_PARK', NULL, 'Manyara', 'Famous for its tree-climbing lions, large flocks of flamingos, and stunning location at the base of the Great Rift Valley escarpment.', '330 km² (including 230 km² of lake surface)', 'lake-manyara-national-park', 'Tree-climbing Lions, Flamingos, Great Rift Valley, Bird Watching, Groundwater Forest, Elephants, Diverse Ecosystems', '2025-12-31 23:59:37.000000', 'Groundwater forest with mahogany and wild mango trees at the park entrance. Acacia woodlands dominate the drier areas. Lush vegetation supported by underground water sources from the escarpment.', 'Tree-climbing lions are the park\'s most famous residents. Large elephant herds, buffaloes, giraffes, zebras, wildebeest, hippos, and a remarkable variety of primates including baboons and blue monkeys. Over 400 bird species recorded.'),
(5, 'Accessible by road from Arusha (45 minutes). Multiple entry gates including Momella Gate and Ngongongare Gate.', 'Year-round; June to February best for Mount Meru trekking', '2025-12-31 23:59:37.000000', 'Arusha', 'Diverse habitats including montane forest, highland moorland, alpine desert, crater floor, alkaline lakes, and open grassland.', '1,500-4,566 meters (Mount Meru summit)', 'Arusha National Park, though small at 137 square kilometers, offers incredible diversity within close proximity to Arusha city. The park is dominated by Mount Meru, an active volcano and Tanzania\'s second-highest mountain at 4,566 meters. The park features three distinct areas: Ngurdoto Crater, the Momella Lakes, and Mount Meru. It is one of the few parks in Tanzania where walking safaris are permitted.', 'Established as a national park in 1960, initially as Ngurdoto Crater National Park. Expanded in 1967 to include Mount Meru and renamed Arusha National Park.', NULL, b'1', -3.2500000, 'Northern Tanzania, 32 km northeast of Arusha City', 36.8333000, 'Arusha National Park', '6:30 AM - 6:30 PM daily', 'NATIONAL_PARK', NULL, 'Arusha', 'Home to Mount Meru (4,566m), Tanzania\'s second-highest peak, featuring stunning landscapes, diverse wildlife, and unique walking safari opportunities.', '137 km²', 'arusha-national-park', 'Mount Meru, Trekking, Colobus Monkeys, Walking Safari, Ngurdoto Crater, Momella Lakes, Bird Watching, Alpine', '2025-12-31 23:59:37.000000', 'Montane forest with tall trees on Mount Meru slopes. Highland moorland and alpine vegetation at higher elevations. Grasslands and swamps around Momella Lakes.', 'Black and white colobus monkeys, blue monkeys, elephants, buffaloes, giraffes, leopards, spotted hyenas, and the rare red duiker. Over 400 bird species.'),
(6, 'Main gate at Marangu. Other gates: Machame, Londorossi, Lemosho, Rongai, Umbwe. Accessible from Moshi (1 hour).', 'January to March and June to October (dry seasons for climbing)', '2025-12-31 23:59:37.000000', 'Moshi Rural', 'Five distinct vegetation zones creating unique habitats from lowland to montane zones.', '1,800-5,895 meters (Uhuru Peak)', 'Kilimanjaro National Park was established to protect Mount Kilimanjaro, Africa\'s highest peak at 5,895 meters and the world\'s tallest free-standing mountain. The mountain features five distinct climatic zones from cultivated farmland through rainforest, heath and moorland, alpine desert, to the arctic summit zone with glaciers. Over 35,000 people attempt to reach Uhuru Peak annually. UNESCO World Heritage Site.', 'Established as a national park in 1973 and designated a UNESCO World Heritage Site in 1987. First summited by Hans Meyer and Ludwig Purtscheller in 1889.', NULL, b'1', -3.0674000, 'Northern Tanzania, near Kenyan border, 128 km from Arusha', 37.3556000, 'Kilimanjaro National Park', '24 hours (climbers register during day)', 'NATIONAL_PARK', NULL, 'Kilimanjaro', 'Home to Mount Kilimanjaro, Africa\'s highest mountain at 5,895 meters, and the world\'s tallest free-standing mountain.', '1,668 km²', 'kilimanjaro-national-park', 'Mount Kilimanjaro, Uhuru Peak, Trekking, UNESCO World Heritage, Africa Highest Mountain, Glaciers, Alpine, Seven Summits', '2025-12-31 23:59:37.000000', 'Montane forest, heath zone with giant heathers, moorland with tussock grasses, alpine zone with giant groundsels and lobelias, glaciers at summit.', 'Elephants, buffaloes, leopards, bushbucks, red duikers, and various primates in lower forests. Over 140 bird species.'),
(7, 'Accessible by air to Mtemere, Kiba, or Siwandu airstrips. Road from Dar es Salaam (5-6 hours).', 'June to October (dry season)', '2025-12-31 23:59:37.000000', 'Liwale', 'Miombo woodland, riverine forests, open grasslands, seasonal swamps, and the Rufiji River system.', '100-1,300 meters', 'Nyerere National Park, created in 2019 from the northern portion of the Selous Game Reserve, is Tanzania\'s largest national park at 30,893 square kilometers. The Rufiji River flows through creating a network of channels, lakes, and swamps. UNESCO World Heritage Site with relatively few tourists.', 'Originally established as a game reserve in 1905. Designated UNESCO World Heritage Site in 1982. Northern sector declared Nyerere National Park in 2019.', NULL, b'1', -7.6667000, 'Southern Tanzania, 219 km from Dar es Salaam', 37.6167000, 'Nyerere National Park', '6:00 AM - 6:00 PM daily', 'NATIONAL_PARK', NULL, 'Morogoro, Ruvuma, and Lindi', 'Africa\'s largest game reserve and UNESCO World Heritage Site, renamed in 2019 to honor President Julius Nyerere.', '30,893 km²', 'nyerere-national-park', 'UNESCO World Heritage, Rufiji River, Wild Dogs, Wilderness, Boat Safari, Elephants, Remote, Nyerere', '2025-12-31 23:59:37.000000', 'Miombo woodland, borassus palms along rivers, grasslands, and riverine forests with mahogany and ebony trees.', 'Over 15,000 elephants, lions, leopards, wild dogs, buffaloes, hippos, crocodiles. Tanzania\'s largest population of endangered African wild dogs. Over 440 bird species.'),
(8, 'Accessible by air to Msembe airstrip. Road from Iringa (4-5 hours on rough roads).', 'June to October (dry season)', '2025-12-31 23:59:37.000000', 'Iringa', 'Miombo woodland, acacia savanna, riverine forests, baobab-studded plains, and the Great Ruaha River valley.', '750-1,868 meters', 'Ruaha National Park is Tanzania\'s largest national park at 20,226 square kilometers. The park is famous for its large elephant population (over 12,000) and has one of the highest concentrations of elephants in East Africa. Renowned for predators, particularly lions. Remote and uncrowded.', 'Originally part of Rungwa Game Reserve in 1910. Upgraded to national park in 1964. Expanded in 2008.', NULL, b'1', -7.9000000, 'Central-southern Tanzania, 130 km from Iringa', 34.8333000, 'Ruaha National Park', '6:00 AM - 6:00 PM daily', 'NATIONAL_PARK', NULL, 'Iringa and Dodoma', 'Tanzania\'s largest national park, featuring the Great Ruaha River and one of Africa\'s largest elephant populations.', '20,226 km²', 'ruaha-national-park', 'Elephants, Lions, Great Ruaha River, Remote, Wild Dogs, Baobabs, Predators, Wilderness', '2025-12-31 23:59:37.000000', 'Miombo woodland, ancient baobabs, acacia species, riverine forests, and Commiphora-Combretum woodlands.', 'Over 12,000 elephants, 30,000+ buffaloes, 10% of Africa\'s lions, leopards, cheetahs, wild dogs. Over 571 bird species.'),
(9, 'Main gate from Dar es Salaam (4-5 hours) via Morogoro. Park bisected by Dar-Iringa highway.', 'Year-round; June to October best for wildlife', '2025-12-31 23:59:37.000000', 'Kilosa', 'Open grassland plains, miombo woodland, acacia savanna, and riverine forests.', '550-1,250 meters', 'Mikumi National Park covers 3,230 square kilometers. Most accessible southern park, 4-5 hours from Dar es Salaam. The Mkata River floodplain is compared to the Serengeti. Excellent year-round wildlife viewing.', 'Established as a national park in 1964. Originally part of the Selous ecosystem.', NULL, b'1', -7.3833000, 'Southern-central Tanzania, 283 km west of Dar es Salaam', 36.9000000, 'Mikumi National Park', '6:00 AM - 6:00 PM daily', 'NATIONAL_PARK', NULL, 'Morogoro', 'The fourth-largest national park, known for reliable wildlife viewing along the main Dar es Salaam-Iringa highway.', '3,230 km²', 'mikumi-national-park', 'Accessible, Mkata Floodplain, Elephants, Lions, Bird Watching, Uluguru Mountains', '2025-12-31 23:59:37.000000', 'Mkata floodplain grasslands, miombo woodland, acacia trees, borassus palms, and riverine forests.', 'Elephants, buffaloes, giraffes, zebras, wildebeest, lions, leopards, wild dogs. Over 400 bird species.'),
(10, 'Main entrance at Mang\'ula village, 65 km from Mikumi or 350 km from Dar es Salaam.', 'Year-round; June to October for hiking', '2025-12-31 23:59:37.000000', 'Kilolo', 'Tropical rainforest, montane forest, miombo woodland, grassland plateaus, streams, and waterfalls.', '250-2,576 meters (Luhombero Peak)', 'Udzungwa Mountains National Park protects 1,990 square kilometers of Eastern Arc Mountains. Unique as it has no roads - explored only on foot. Endemic species including Iringa red colobus and Sanje mangabey. Sanje Waterfall plunges 170 meters.', 'Gazetted as national park in 1992. Previously a forest reserve.', NULL, b'1', -7.7500000, 'Southern-central Tanzania, 350 km southwest of Dar es Salaam', 36.5000000, 'Udzungwa Mountains National Park', '7:00 AM - 5:00 PM daily', 'NATIONAL_PARK', NULL, 'Morogoro', 'A biodiversity hotspot featuring pristine rainforest, endemic primates, spectacular waterfalls, and excellent hiking.', '1,990 km²', 'udzungwa-mountains-national-park', 'Hiking, Waterfalls, Endemic Species, Primates, Rainforest, Biodiversity Hotspot, Eastern Arc', '2025-12-31 23:59:37.000000', 'Pristine tropical rainforest, montane forest, highland grasslands, rich understory vegetation.', 'Six primate species including endemic Iringa red colobus and Sanje mangabey. Forest elephants, buffaloes. Over 400 bird species.'),
(11, 'Accessible by air to Ikuu airstrip. Road access difficult, 40 km from Mpanda.', 'June to October (dry season)', '2025-12-31 23:59:37.000000', 'Mpanda', 'Katuma River floodplains, seasonal lakes, miombo woodland, riverine forests, open grasslands.', '900-1,200 meters', 'Katavi National Park is Tanzania\'s third-largest park and one of its most remote. Famous for highest concentrations of hippos and crocodiles in Africa. Buffalo herds can number in the thousands. Remote with more lions than tourists.', 'Established as national park in 1974. Named after spirit Katabi believed to have lived in tamarind tree near Lake Katavi.', NULL, b'1', -6.9167000, 'Western Tanzania, 40 km south of Mpanda', 31.2000000, 'Katavi National Park', '6:00 AM - 6:00 PM daily', 'NATIONAL_PARK', NULL, 'Katavi', 'One of Tanzania\'s most remote wilderness areas, famous for huge buffalo herds and hippo concentrations.', '4,471 km²', 'katavi-national-park', 'Remote, Wilderness, Buffalo Herds, Hippos, Crocodiles, Western Circuit, Unspoiled', '2025-12-31 23:59:37.000000', 'Miombo woodland, floodplain grasslands, palm-fringed pools, riverine forests.', 'Huge buffalo herds (1,000+), densest hippo/crocodile concentrations, elephants, lions, leopards, giraffes. Over 400 bird species.'),
(12, 'Accessible only by boat or flight. 2-3 hour boat from Kigoma. No roads.', 'May to October (dry season)', '2025-12-31 23:59:37.000000', 'Kigoma Rural', 'Montane forest, lowland rainforest, miombo woodland, grassland, bamboo forests, Lake Tanganyika shoreline.', '772-2,462 meters (Mount Nkungwe)', 'Mahale Mountains National Park protects 1,613 square kilometers on Lake Tanganyika shores. Home to approximately 1,000 wild chimpanzees with one habituated group. Completely remote with no roads - access only by boat. Crystal-clear waters offer excellent snorkeling.', 'Established as national park in 1985. Japanese primatologist Dr. Toshisada Nishida began chimpanzee research in 1960s.', NULL, b'1', -6.2500000, 'Western Tanzania, Lake Tanganyika shore, 120 km south of Kigoma', 29.9167000, 'Mahale Mountains National Park', '6:00 AM - 6:00 PM daily', 'NATIONAL_PARK', NULL, 'Kigoma', 'A remote paradise on Lake Tanganyika, home to wild chimpanzees, accessible only by boat.', '1,613 km²', 'mahale-mountains-national-park', 'Chimpanzees, Lake Tanganyika, Remote, Primate Trekking, Snorkeling, Mountains, Western Circuit', '2025-12-31 23:59:37.000000', 'Montane evergreen forest, lowland rainforest, miombo woodland, bamboo at higher elevations.', '1,000 wild chimpanzees, eight other primate species, leopards, bushbucks. Over 355 bird species. Lake has 250+ endemic fish species.'),
(13, 'Accessible only by boat from Kigoma (30 minutes to 1 hour). No road access.', 'Year-round; June to October best for chimpanzees', '2025-12-31 23:59:37.000000', 'Kigoma Rural', 'Lowland evergreen forest in valleys, miombo woodland on ridges, grassland plateaus, Lake Tanganyika shoreline.', '772-1,500 meters', 'Gombe Stream is Tanzania\'s smallest park at 52 square kilometers but globally renowned as Dr. Jane Goodall\'s chimpanzee research site since 1960 - the world\'s longest-running wildlife research project. About 100 habituated chimpanzees live in Gombe.', 'Established as game reserve in 1943, upgraded to national park in 1968. Jane Goodall arrived in 1960.', NULL, b'1', -4.6667000, 'Western Tanzania, Lake Tanganyika shore, 16 km north of Kigoma', 29.6167000, 'Gombe Stream National Park', '6:00 AM - 6:00 PM daily', 'NATIONAL_PARK', NULL, 'Kigoma', 'Tanzania\'s smallest park, world-famous as Jane Goodall\'s chimpanzee research site since 1960.', '52 km²', 'gombe-stream-national-park', 'Chimpanzees, Jane Goodall, Research, Lake Tanganyika, Primates, Western Circuit, Small Park', '2025-12-31 23:59:37.000000', 'Gallery forest in valleys, miombo woodland on slopes, grasslands on plateaus.', '100 chimpanzees with habituated groups, red-tailed monkeys, red colobus, blue monkeys, olive baboons, bushbucks. Over 200 bird species.'),
(14, 'Accessible by boat from Nkome (3.5 hours) or Muganza (1 hour). Fly to Rubondo airstrip.', 'Year-round; June to October for chimpanzees and fishing', '2025-12-31 23:59:37.000000', 'Biharamulo', 'Closed-canopy tropical forest, papyrus wetlands, savanna, rocky shores, sandy beaches, Lake Victoria waters.', '1,134-1,486 meters', 'Rubondo Island National Park comprises islands in Lake Victoria. 90% covered in dense forest. Unique as successful wildlife introduction site with chimpanzees introduced in 1960s. One of few places to observe wild chimpanzees and spot sitatunga. Over 400 bird species.', 'Declared national park in 1977. Wildlife introduction site starting in 1960s under Frankfurt Zoological Society.', NULL, b'1', -2.3000000, 'Northwestern Tanzania, island in Lake Victoria, west of Mwanza', 31.8333000, 'Rubondo Island National Park', '6:00 AM - 6:00 PM daily', 'NATIONAL_PARK', NULL, 'Geita', 'A pristine island in Lake Victoria, offering unique forest-lake ecosystems with introduced chimps and rare sitatunga.', '457 km²', 'rubondo-island-national-park', 'Island, Lake Victoria, Chimpanzees, Sitatunga, Bird Watching, Fishing, Remote, Forest', '2025-12-31 23:59:37.000000', 'Dense tropical forest with mahogany and fig trees, papyrus swamps, open grasslands, aquatic vegetation.', 'Introduced chimpanzees, elephants, giraffes, suni, roan antelopes. Indigenous sitatunga, hippos, crocodiles, otters, bushbucks. Over 400 bird species.'),
(15, 'Accessible by road from Dar es Salaam (2.5-3 hours). Also by boat along coast or Wami River.', 'Year-round; June to October for wildlife; November to February for turtles', '2025-12-31 23:59:37.000000', 'Bagamoyo and Pangani', 'Beaches, mangrove forests, salt flats, acacia woodlands, riverine forests, grasslands, Wami River system.', '0-200 meters', 'Saadani National Park is unique as Tanzania\'s only coastal wildlife sanctuary where beach meets bush. Covers 1,062 square kilometers with 30 kilometers of Indian Ocean coastline. Hosts four of the Big Five. Beaches are important green turtle nesting sites. Historic Saadani village was once a 19th-century trading port.', 'Gazetted as national park in 2005, combining Saadani Game Reserve, Mkwaja Ranch, Wami River, and Zaraninge Forest.', NULL, b'1', -6.0000000, 'Coastal Tanzania, 45 km north of Bagamoyo, 100 km north of Dar es Salaam', 38.7667000, 'Saadani National Park', '6:00 AM - 6:00 PM daily', 'NATIONAL_PARK', NULL, 'Pwani', 'Tanzania\'s only wildlife sanctuary bordering the Indian Ocean, combining beach and bush safari.', '1,062 km²', 'saadani-national-park', 'Beach, Coastal, Ocean, Unique, Wami River, Turtles, Boat Safari, Historic, Beach Safari', '2025-12-31 23:59:37.000000', 'Coastal mangrove forests, acacia woodlands, palm trees, riverine vegetation, coastal dune vegetation.', 'Four of Big Five: elephants, lions, leopards, buffaloes. Giraffes, wildebeest, hippos, crocodiles, green turtles. Over 300 bird species.'),
(16, 'Accessible by air (30-minute flight from Dar) or boat. Main settlements: Kilindoni, Utende, Chole Island.', 'Year-round; October to March for whale sharks', '2025-12-31 23:59:37.000000', 'Mafia', 'Coral reefs, seagrass beds, mangrove forests, tidal channels, sandy beaches, open ocean.', '0-50 meters', 'Mafia Island Marine Park, established in 1995 as Tanzania\'s first marine park, protects 822 square kilometers. Globally renowned for whale shark encounters (October to March). Coral reefs support over 400 fish species. Five sea turtle species nest on beaches. UNESCO World Heritage Site.', 'Gazetted in 1995 as Tanzania\'s first marine park. Historical significance with 13th-century ruins.', NULL, b'1', -7.9167000, 'Indian Ocean, 120 km southeast of Dar es Salaam', 39.7500000, 'Mafia Island Marine Park', 'Accessible 24/7', 'MARINE_PARK', NULL, 'Pwani', 'Tanzania\'s first marine protected area, renowned for pristine coral reefs, whale sharks, and world-class diving.', '822 km²', 'mafia-island-marine-park', 'Marine Park, Diving, Snorkeling, Whale Sharks, Coral Reefs, Sea Turtles, Island, Indian Ocean', '2025-12-31 23:59:37.000000', 'Extensive seagrass beds, eight mangrove species, diverse hard and soft coral species.', 'Over 400 fish species, whale sharks (seasonal), manta rays, five sea turtle species, dolphins, dugongs (rare), humpback whales (seasonal).'),
(17, 'Accessible from Mtwara town (20 km). Fly to Mtwara from Dar or drive (10-12 hours).', 'Year-round; June to October for diving; November to February for turtles', '2025-12-31 23:59:37.000000', 'Mtwara Rural', 'Coral reefs, extensive mangrove forests, seagrass meadows, sandy beaches, rocky shores, Ruvuma River estuary.', '0-100 meters', 'Mnazi Bay-Ruvuma Estuary Marine Park protects 650 square kilometers at Tanzania\'s southern border extending to Mozambique. Established in 2000, it\'s one of Tanzania\'s most pristine marine areas. Five sea turtle species nest on beaches. Excellent snorkeling and diving with minimal tourist pressure.', 'Gazetted as marine park in 2000. Minimal development preserves wild character.', NULL, b'1', -10.3833000, 'Far southern Tanzania, 396 km south of Dar es Salaam, near Mozambique border', 40.3500000, 'Mnazi Bay-Ruvuma Estuary Marine Park', 'Accessible 24/7', 'MARINE_PARK', NULL, 'Mtwara', 'A pristine marine park at Tanzania\'s southern border with diverse coral reefs, mangroves, and turtle nesting sites.', '650 km²', 'mnazi-bay-ruvuma-estuary-marine-park', 'Marine Park, Remote, Pristine, Diving, Snorkeling, Sea Turtles, Mangroves, Coral Reefs', '2025-12-31 23:59:37.000000', 'Extensive mangrove forests (nine species), seagrass beds, diverse coral species, coastal vegetation.', 'Over 400 fish species, five sea turtle species, humpback whales (seasonal), dolphins, dugongs (rare), rays.'),
(18, 'Main gate at Zange, 112 km from Moshi. Accessible from Arusha (5-6 hours) or from Dar via Tanga.', 'June to February', '2025-12-31 23:59:37.000000', 'Same', 'Acacia-commiphora bushland, open grasslands, rocky hills, seasonal rivers, baobab-studded landscapes.', '230-1,570 meters', 'Mkomazi National Park covers 3,245 square kilometers forming continuous ecosystem with Kenya\'s Tsavo West. Upgraded to national park in 2008. Significant for black rhino sanctuary and African wild dog conservation programs. Spectacular views of Kilimanjaro and Usambara Mountains. Undervisited wilderness.', 'Originally gazetted as game reserve in 1951. Upgraded to national park in 2008. Black rhino sanctuary established 1997.', NULL, b'1', -4.2500000, 'Northern Tanzania, 112 km from Moshi, borders Kenya', 37.9167000, 'Mkomazi National Park', '6:00 AM - 6:00 PM daily', 'NATIONAL_PARK', NULL, 'Kilimanjaro and Tanga', 'A vital sanctuary for endangered black rhinos and African wild dogs with spectacular Kilimanjaro views.', '3,245 km²', 'mkomazi-national-park', 'Black Rhino, Wild Dogs, Conservation, Kilimanjaro Views, Endangered Species, Remote, Northern Circuit', '2025-12-31 23:59:37.000000', 'Acacia and commiphora bushland, ancient baobabs, grasslands with scattered trees, vegetation adapted to semi-arid conditions.', 'Black rhinos (in sanctuary), African wild dogs (breeding program), elephants, giraffes, elands, lesser kudu, gerenuk, fringe-eared oryx, lions, leopards. Over 450 bird species.');

